// Answer callback query to remove loading state
// The library expects answerCallbackQuery format
if (msg.payload && msg.payload.callback_query_id) {
    // Format for answerCallbackQuery
    msg.payload = {
        callback_query_id: msg.payload.callback_query_id,
        text: msg.payload.text || '',
        show_alert: msg.payload.show_alert || false
    };
    msg.topic = 'answerCallbackQuery';
    return msg;
}
return null;

// Configuration: Get allowed user IDs from environment
const ALLOWED_USER_IDS = (env.get('TELEGRAM_ALLOWED_USERS') || '').split(',').map(id => parseInt(id.trim())).filter(id => !isNaN(id));

// Extract message data from telegrambot node (per library API: https://flows.nodered.org/node/node-red-contrib-telegrambot)
// msg.payload contains: chatId, type, content
// msg.originalMessage contains full original message
const payload = msg.payload || {};
let chatId = payload.chatId;
const messageType = payload.type;
let text = (payload.content || '').trim();

// Get user info from originalMessage
const originalMsg = msg.originalMessage || {};
let userId = originalMsg.from ? originalMsg.from.id : null;
const messageId = originalMsg.message_id;

// Handle callback queries from inline keyboard buttons
let answerCallback = null;
if (messageType === 'callback_query') {
    // Extract callback data - check multiple possible locations
    // Event node might use: payload.data, payload.callback_data, payload.content
    // Or originalMessage.data
    text = payload.data || payload.callback_data || payload.content || 
           (originalMsg.data ? originalMsg.data : '') || '';

    // Get chatId from callback query message if not in payload
    if (!chatId) {
        if (originalMsg.message && originalMsg.message.chat) {
            chatId = originalMsg.message.chat.id;
        } else if (originalMsg.chat) {
            chatId = originalMsg.chat.id;
        }
    }

    // Get user info from callback query
    if (originalMsg.from) {
        userId = originalMsg.from.id;
    }

    // Store callback query ID for answering - check multiple locations
    const callbackQueryId = payload.callback_query_id || payload.id || 
                            (originalMsg.id ? originalMsg.id.toString() : null) ||
                            (originalMsg.query_id ? originalMsg.query_id.toString() : null);

    // Prepare answer callback query message (output 2)
    if (callbackQueryId) {
        answerCallback = {
            payload: {
                callback_query_id: callbackQueryId,
                text: '',
                show_alert: false
            },
            topic: 'answerCallbackQuery'
        };
    }

    // Debug: log callback query structure (remove in production)
    node.warn('Callback Query Debug: ' + JSON.stringify({payload, originalMsg, text, chatId, callbackQueryId}));
}

// Check if it's a text message or callback query
if ((messageType !== 'message' && messageType !== 'callback_query') || !text || !chatId) {
    return [null, answerCallback].filter(m => m !== null); // Return answer callback if exists
}

// Authorization check
if (ALLOWED_USER_IDS.length > 0 && userId && !ALLOWED_USER_IDS.includes(userId)) {
    msg.payload = {
        chatId: chatId,
        type: 'message',
        content: '❌ Unauthorized. You are not allowed to use this bot.'
    };
    msg.topic = 'unauthorized';
    return msg;
}

// Store chat ID for notifications
if (!flow.get('telegram_chat_ids')) {
    flow.set('telegram_chat_ids', []);
}
const chatIds = flow.get('telegram_chat_ids');
if (!chatIds.includes(chatId)) {
    chatIds.push(chatId);
    flow.set('telegram_chat_ids', chatIds);
}

// Parse command
const command = text.split(' ')[0].toLowerCase();
const args = text.split(' ').slice(1);

// Check if it's a gate command - let dedicated gate flows handle these
if (command.startsWith('/gate_') || command === '/gate' || command.startsWith('/sliding_') || command.startsWith('/secondary_') || command.startsWith('/garden') || command.startsWith('/lights_')) {
    // Return only the answer callback (if exists), don't process the command here
    return [null, answerCallback].filter(m => m !== null);
}

// Store telegram data in msg
msg.telegram = {
    chatId: chatId,
    userId: userId,
    messageId: messageId,
    command: command,
    args: args,
    originalText: text
};

// Route to appropriate handler
if (command === '/boot') {
    msg.topic = 'boot';
} else if (command === '/shutdown' || command === '/stop') {
    msg.topic = 'shutdown';
} else if (command === '/force' || command === '/force_shutdown') {
    msg.topic = 'force';
} else if (command === '/status' || command === '/state') {
    msg.topic = 'status';
} else if (command === '/help' || command === '/start') {
    msg.topic = 'help';
} else if (command === '/commands' || command === '/list') {
    msg.topic = 'commands';
} else {
    msg.topic = 'unknown';
}

// Return main message and answer callback (if exists)
return [msg, answerCallback].filter(m => m !== null);

const args = msg.telegram.args;
const server = args.length > 0 ? args[0].toLowerCase() : 'dell';

let topic, method, serverName;

if (server === 'hp' || server === 'dl360p') {
    topic = 'hp/dl360p/command/boot';
    method = 'ilo';
    serverName = 'HP DL360p';
} else if (server === 'dell' || server === 't310') {
    topic = 'dell/t310/command/boot';
    method = 'wol';
    serverName = 'Dell T310';
} else {
    msg.payload = {
        chatId: msg.telegram.chatId,
        type: 'message',
        content: `❌ Unknown server: ${server}\n\nUsage: /boot [dell|hp]`
    };
    msg.topic = 'send';
    return msg;
}

// Create MQTT command payload
const timestamp = new Date().toISOString();
const requestId = `telegram-boot-${Date.now()}`;

// Store original telegram data
const telegramData = msg.telegram;

// Create MQTT message
msg.payload = {
    action: 'boot',
    method: method,
    timestamp: timestamp,
    request_id: requestId
};

msg.topic = topic;
msg.telegram = telegramData;
msg.telegram.serverName = serverName;
msg.telegram.commandType = 'boot';

// Create confirmation message for Telegram
const confirmationMsg = {
    ...msg,
    payload: {
        chatId: telegramData.chatId,
        type: 'message',
        content: `🟢 Booting ${serverName}...\n\nMethod: ${method.toUpperCase()}\nRequest ID: ${requestId}`
    },
    topic: 'send'
};

// Send both MQTT command and Telegram confirmation
return [msg, confirmationMsg];

